// Number of doubles per 512-bit word
#define DOUBLES_PER_WORD (LARGE_BUS / 64)

// Wide-bus read: dst[0..n_bytes/8-1] <- src wide bus starting at byte offset
static void memcpy_wide_bus_read_double(double* dst, const MARS_WIDE_BUS_TYPE* src,
                                         long long byte_offset, long long n_bytes) {
#pragma HLS INLINE
    long long n_elem = n_bytes / sizeof(double);
    long long word_offset = byte_offset / sizeof(MARS_WIDE_BUS_TYPE);
    long long elem_start  = (byte_offset % sizeof(MARS_WIDE_BUS_TYPE)) / sizeof(double);

    long long elem_idx = 0;
    long long wrd = word_offset;
    long long lane = elem_start;
    for (long long e = 0; e < n_elem; e++) {
#pragma HLS PIPELINE II=1
        MARS_WIDE_BUS_TYPE word = src[wrd];
        ap_uint<64> bits = word.range(lane * 64 + 63, lane * 64);
        double val;
        memcpy(&val, &bits, sizeof(double));
        dst[e] = val;
        lane++;
        if (lane == DOUBLES_PER_WORD) { lane = 0; wrd++; }
    }
}

// Wide-bus write: dst wide bus starting at byte offset <- src[0..n_bytes/8-1]
static void memcpy_wide_bus_write_double(MARS_WIDE_BUS_TYPE* dst, const double* src,
                                          long long byte_offset, long long n_bytes) {
#pragma HLS INLINE
    long long n_elem = n_bytes / sizeof(double);
    long long word_offset = byte_offset / sizeof(MARS_WIDE_BUS_TYPE);
    long long elem_start  = (byte_offset % sizeof(MARS_WIDE_BUS_TYPE)) / sizeof(double);

    long long wrd = word_offset;
    long long lane = elem_start;
    MARS_WIDE_BUS_TYPE word = 0;
    // If not aligned to word boundary, read first partial word
    if (lane != 0) word = dst[wrd];

    for (long long e = 0; e < n_elem; e++) {
#pragma HLS PIPELINE II=1
        double val = src[e];
        ap_uint<64> bits;
        memcpy(&bits, &val, sizeof(double));
        word.range(lane * 64 + 63, lane * 64) = bits;
        lane++;
        if (lane == DOUBLES_PER_WORD) {
            dst[wrd] = word;
            wrd++;
            lane = 0;
            word = 0;
        }
    }
    // flush last partial word
    if (lane != 0) {
        // read-modify-write for partial tail
        MARS_WIDE_BUS_TYPE tail = dst[wrd];
        ap_uint<64> mask_base;
        for (long long l = 0; l < lane; l++) {
            tail.range(l * 64 + 63, l * 64) = word.range(l * 64 + 63, l * 64);
        }
        dst[wrd] = tail;
    }
}
